    "spec": "{\"$schema\":\"https://vega.github.io/schema/vega/v6.json\",\"description\":\"A searchable, stacked area chart of U.S. occupations from 1850 to 2000.\",\"width\":800,\"height\":500,\"padding\":5,\"signals\":[{\"name\":\"sex\",\"value\":\"all\",\"bind\":{\"input\":\"radio\",\"options\":[\"men\",\"women\",\"all\"]}},{\"name\":\"query\",\"value\":\"\",\"on\":[{\"events\":\"area:click!\",\"update\":\"datum.job\"},{\"events\":\"dblclick!\",\"update\":\"''\"}],\"bind\":{\"input\":\"text\",\"placeholder\":\"search\",\"autocomplete\":\"off\"}}],\"data\":[{\"name\":\"jobs\",\"url\":\"https://vega.github.io/vega/data/jobs.json\",\"transform\":[{\"type\":\"filter\",\"expr\":\"(sex === 'all' || datum.sex === sex) && (!query || test(regexp(query,'i'), datum.job))\"},{\"type\":\"stack\",\"field\":\"perc\",\"groupby\":[\"year\"],\"sort\":{\"field\":[\"job\",\"sex\"],\"order\":[\"descending\",\"descending\"]}}]},{\"name\":\"series\",\"source\":\"jobs\",\"transform\":[{\"type\":\"aggregate\",\"groupby\":[\"job\",\"sex\"],\"fields\":[\"perc\",\"perc\"],\"ops\":[\"sum\",\"argmax\"],\"as\":[\"sum\",\"argmax\"]}]}],\"scales\":[{\"name\":\"x\",\"type\":\"linear\",\"range\":\"width\",\"zero\":false,\"round\":true,\"domain\":{\"data\":\"jobs\",\"field\":\"year\"}},{\"name\":\"y\",\"type\":\"linear\",\"range\":\"height\",\"round\":true,\"zero\":true,\"domain\":{\"data\":\"jobs\",\"field\":\"y1\"}},{\"name\":\"color\",\"type\":\"ordinal\",\"domain\":[\"men\",\"women\"],\"range\":[\"#33f\",\"#f33\"]},{\"name\":\"alpha\",\"type\":\"linear\",\"zero\":true,\"domain\":{\"data\":\"series\",\"field\":\"sum\"},\"range\":[0.4,0.8]},{\"name\":\"font\",\"type\":\"sqrt\",\"range\":[0,20],\"round\":true,\"zero\":true,\"domain\":{\"data\":\"series\",\"field\":\"argmax.perc\"}},{\"name\":\"opacity\",\"type\":\"quantile\",\"range\":[0,0,0,0,0,0.1,0.2,0.4,0.7,1],\"domain\":{\"data\":\"series\",\"field\":\"argmax.perc\"}},{\"name\":\"align\",\"type\":\"quantize\",\"range\":[\"left\",\"center\",\"right\"],\"zero\":false,\"domain\":[1730,2130]},{\"name\":\"offset\",\"type\":\"quantize\",\"range\":[6,0,-6],\"zero\":false,\"domain\":[1730,2130]}],\"axes\":[{\"orient\":\"bottom\",\"scale\":\"x\",\"format\":\"d\",\"tickCount\":15},{\"orient\":\"right\",\"scale\":\"y\",\"format\":\"%\",\"grid\":true,\"domain\":false,\"tickSize\":12,\"encode\":{\"grid\":{\"enter\":{\"stroke\":{\"value\":\"#ccc\"}}},\"ticks\":{\"enter\":{\"stroke\":{\"value\":\"#ccc\"}}}}}],\"marks\":[{\"type\":\"group\",\"from\":{\"data\":\"series\",\"facet\":{\"name\":\"facet\",\"data\":\"jobs\",\"groupby\":[\"job\",\"sex\"]}},\"marks\":[{\"type\":\"area\",\"from\":{\"data\":\"facet\"},\"encode\":{\"update\":{\"x\":{\"scale\":\"x\",\"field\":\"year\"},\"y\":{\"scale\":\"y\",\"field\":\"y0\"},\"y2\":{\"scale\":\"y\",\"field\":\"y1\"},\"fill\":{\"scale\":\"color\",\"field\":\"sex\"},\"fillOpacity\":{\"scale\":\"alpha\",\"field\":{\"parent\":\"sum\"}}},\"hover\":{\"fillOpacity\":{\"value\":0.2}}}}]},{\"type\":\"text\",\"from\":{\"data\":\"series\"},\"interactive\":false,\"encode\":{\"update\":{\"x\":{\"scale\":\"x\",\"field\":\"argmax.year\"},\"dx\":{\"scale\":\"offset\",\"field\":\"argmax.year\"},\"y\":{\"signal\":\"scale('y', 0.5 * (datum.argmax.y0 + datum.argmax.y1))\"},\"fill\":{\"value\":\"#000\"},\"fillOpacity\":{\"scale\":\"opacity\",\"field\":\"argmax.perc\"},\"fontSize\":{\"scale\":\"font\",\"field\":\"argmax.perc\",\"offset\":5},\"text\":{\"field\":\"job\"},\"align\":{\"scale\":\"align\",\"field\":\"argmax.year\"},\"baseline\":{\"value\":\"middle\"}}}}]}"
